+type Position = {
+  index: number;
+  line: number;
+  column: number;
+};
+
+type TextNode = { type: "text"; value: string };
+type ValueNode = { type: "value"; path: string; escaped: boolean; position: Position };
+type IfNode = { type: "if"; path: string; body: Node[]; alternate: Node[]; position: Position };
+type EachNode = { type: "each"; path: string; body: Node[]; alternate: Node[]; position: Position };
+type Node = TextNode | ValueNode | IfNode | EachNode;
+type BlockNode = IfNode | EachNode;
+
+type Frame = {
+  node: BlockNode;
+  parent: Node[];
+  inElse: boolean;
+};
+
+type Context = {
+  root: unknown;
+  current: unknown;
+  index?: number;
+};
+
+function positionAt(source: string, index: number): Position {
+  const before = source.slice(0, index);
+  const lines = before.split("\n");
+  return { index, line: lines.length, column: lines[lines.length - 1].length + 1 };
+}
+
+function syntaxError(message: string, position: Position): Error {
+  return new Error(`${message} at line ${position.line}, column ${position.column}`);
+}
+
+function parse(source: string): Node[] {
+  const root: Node[] = [];
+  const stack: Frame[] = [];
+  let target = root;
+  let cursor = 0;
+
+  while (cursor < source.length) {
+    const open = source.indexOf("{{", cursor);
+    if (open === -1) {
+      target.push({ type: "text", value: source.slice(cursor) });
+      break;
+    }
+    if (open > cursor) target.push({ type: "text", value: source.slice(cursor, open) });
+
+    const triple = source.startsWith("{{{", open);
+    const closeMarker = triple ? "}}}" : "}}";
+    const contentStart = open + (triple ? 3 : 2);
+    const close = source.indexOf(closeMarker, contentStart);
+    const position = positionAt(source, open);
+    if (close === -1) throw syntaxError("Unclosed tag", position);
+
+    const content = source.slice(contentStart, close).trim();
+    cursor = close + closeMarker.length;
+    if (!content) throw syntaxError("Empty tag", position);
+
+    if (triple) {
+      target.push({ type: "value", path: content, escaped: false, position });
+      continue;
+    }
+    if (content.startsWith("!")) continue;
+
+    if (content.startsWith("#")) {
+      const match = /^#(if|each)\s+(.+)$/.exec(content);
+      if (!match) throw syntaxError(`Unknown block tag {{${content}}}`, position);
+      const kind = match[1] as "if" | "each";
+      const path = match[2].trim();
+      if (!path) throw syntaxError(`Missing path for ${kind} block`, position);
+      const node: BlockNode = { type: kind, path, body: [], alternate: [], position };
+      target.push(node);
+      stack.push({ node, parent: target, inElse: false });
+      target = node.body;
+      continue;
+    }
+
+    if (content === "else") {
+      const frame = stack[stack.length - 1];
+      if (!frame) throw syntaxError("Else outside a block", position);
+      if (frame.inElse) throw syntaxError("Duplicate else", position);
+      frame.inElse = true;
+      target = frame.node.alternate;
+      continue;
+    }
+
+    if (content.startsWith("/")) {
+      const name = content.slice(1).trim();
+      if (name !== "if" && name !== "each") {
+        throw syntaxError(`Unknown closing block {{${content}}}`, position);
+      }
+      const frame = stack[stack.length - 1];
+      if (!frame) throw syntaxError(`Closing ${name} without an open block`, position);
+      if (frame.node.type !== name) {
+        throw syntaxError(`Mismatched closing block: expected /${frame.node.type}, got /${name}`, position);
+      }
+      stack.pop();
+      target = frame.parent;
+      continue;
+    }
+
+    target.push({ type: "value", path: content, escaped: true, position });
+  }
+
+  const frame = stack[stack.length - 1];
+  if (frame) throw syntaxError(`Unclosed ${frame.node.type} block`, frame.node.position);
+  return root;
+}
+
+function property(value: unknown, part: string): unknown {
+  if ((typeof value !== "object" || value === null) && typeof value !== "function") return undefined;
+  if (!Object.prototype.hasOwnProperty.call(value, part)) return undefined;
+  return (value as Record<string, unknown>)[part];
+}
+
+function pathValue(value: unknown, path: string): unknown {
+  let result = value;
+  for (const part of path.split(".")) {
+    if (!part) return undefined;
+    result = property(result, part);
+    if (result === undefined) return undefined;
+  }
+  return result;
+}
+
+function resolve(path: string, context: Context): unknown {
+  if (path === "this") return context.current;
+  if (path === "@index") return context.index;
+  if (path.startsWith("this.")) return pathValue(context.current, path.slice(5));
+
+  const local = pathValue(context.current, path);
+  return local === undefined ? pathValue(context.root, path) : local;
+}
+
+function truthy(value: unknown): boolean {
+  if (value === "" || value === 0 || value === false || value == null) return false;
+  return !Array.isArray(value) || value.length > 0;
+}
+
+function scalar(value: unknown, position: Position): string {
+  if (value == null) return "";
+  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean" || typeof value === "bigint") {
+    return String(value);
+  }
+  throw syntaxError(`Cannot render ${typeof value} value as text`, position);
+}
+
+function escapeHtml(value: string): string {
+  return value.replace(/[&<>"']/g, (character) => ({
+    "&": "&amp;",
+    "<": "&lt;",
+    ">": "&gt;",
+    '"': "&quot;",
+    "'": "&#39;",
+  })[character]!);
+}
+
+function renderNodes(nodes: Node[], context: Context): string {
+  let output = "";
+  for (const node of nodes) {
+    if (node.type === "text") {
+      output += node.value;
+    } else if (node.type === "value") {
+      const value = scalar(resolve(node.path, context), node.position);
+      output += node.escaped ? escapeHtml(value) : value;
+    } else if (node.type === "if") {
+      output += renderNodes(truthy(resolve(node.path, context)) ? node.body : node.alternate, context);
+    } else {
+      const value = resolve(node.path, context);
+      if (Array.isArray(value) && value.length > 0) {
+        for (let index = 0; index < value.length; index++) {
+          output += renderNodes(node.body, { root: context.root, current: value[index], index });
+        }
+      } else {
+        output += renderNodes(node.alternate, context);
+      }
+    }
+  }
+  return output;
+}
+
+export function render(template: string, data: unknown): string {
+  return renderNodes(parse(template), { root: data, current: data });
+}
