+import { render } from "./engine";
+
+async function main(): Promise<void> {
+  const [templatePath, dataPath, ...extra] = Bun.argv.slice(2);
+  if (!templatePath || !dataPath || extra.length > 0) {
+    throw new Error("Usage: bun run src/cli.ts TEMPLATE_FILE DATA.json");
+  }
+
+  const [template, json] = await Promise.all([
+    Bun.file(templatePath).text(),
+    Bun.file(dataPath).text(),
+  ]);
+  process.stdout.write(render(template, JSON.parse(json)));
+}
+
+main().catch((error: unknown) => {
+  const message = error instanceof Error ? error.message : String(error);
+  process.stderr.write(`${message}\n`);
+  process.exitCode = 1;
+});
*** Add File: test/engine.test.ts
+import { describe, expect, test } from "bun:test";
+import { render } from "../src/engine";
+
+describe("render", () => {
+  test("interpolates escaped and raw scalar values", () => {
+    expect(render(`{{value}} {{{value}}} {{missing}}`, { value: `&<>"'` }))
+      .toBe(`&amp;&lt;&gt;&quot;&#39; &<>"' `);
+  });
+
+  test("preserves whitespace and removes comments", () => {
+    expect(render(" a\n {{! ignored }} b ", {})).toBe(" a\n  b ");
+  });
+
+  test("renders nested conditions with specified truthiness", () => {
+    const template = "{{#if outer}}A{{#if inner}}B{{else}}C{{/if}}{{else}}D{{/if}}";
+    expect(render(template, { outer: true, inner: 0 })).toBe("AC");
+    expect(render(template, { outer: [] })).toBe("D");
+    expect(render("{{#if value}}T{{else}}F{{/if}}", { value: {} })).toBe("T");
+  });
+
+  test("iterates arrays with item, index, root fallback, and nesting", () => {
+    const template = "{{#each groups}}[{{name}}/{{title}}:{{#each values}}{{@index}}={{this}};{{else}}empty{{/each}}]{{/each}}";
+    expect(render(template, {
+      title: "root",
+      groups: [{ name: "one", values: ["a", "b"] }, { name: "two", values: [] }],
+    })).toBe("[one/root:0=a;1=b;][two/root:empty]");
+  });
+
+  test("uses each else for non-arrays", () => {
+    expect(render("{{#each items}}item{{else}}none{{/each}}", { items: "no" })).toBe("none");
+  });
+
+  test("rejects non-scalar interpolation", () => {
+    expect(() => render("{{value}}", { value: {} })).toThrow("Cannot render object value as text at line 1, column 1");
+  });
+
+  test.each([
+    ["{{else}}", "Else outside a block at line 1, column 1"],
+    ["{{#if a}}{{else}}{{else}}{{/if}}", "Duplicate else"],
+    ["{{#if a}}{{/each}}", "Mismatched closing block"],
+    ["x\n{{#if a}}", "Unclosed if block at line 2, column 1"],
+    ["{{#wat a}}", "Unknown block tag"],
+    ["{{/wat}}", "Unknown closing block"],
+  ])("reports structural error for %s", (template, message) => {
+    expect(() => render(template, {})).toThrow(message);
+  });
+});
