+      const frame = stack[stack.length - 1];
+      if (!frame) throw syntaxError("Else outside a block", position);
+      if (frame.inElse) throw syntaxError("Duplicate else", position);
+      frame.inElse = true;
+      target = frame.node.alternate;
+      continue;
